NPC_ROLE = {'torv': 'veteran guild master', 'elara': 'compassionate clinic healer', 'brann': 'gruff blacksmith', 'mara': 'sharp market trader', 'hale': 'stern city guard captain', 'pell': 'nervous scavenger', 'fenwick': 'old forest hermit', 'aldous': 'scholarly archivist',
            'barnaby': 'weathered ferry-boat keeper', 'greta': 'road warrior', 'durn': 'miner foreman', 'rashid': 'desert caravan merchant', 'ulf': 'frost-bitten mountain hermit', 'sael': 'ember-wastes fire-caller', 'voss': 'battle-scarred citadel soldier', 'watcher': 'mysterious ageless watcher of the abyss', 'whitlock': 'grizzled ghost-town sheriff', 'sylwen': 'tall silver-haired fey warden', 'okoro': 'starship survivor officer with a chrome arm', 'marrow': 'ghost of a drowned ship captain', 'cobb': 'weary railroad stationmaster', 'slick': 'smooth outlaw fixer with a scarred cheek', 'dale': 'tired gas station attendant', 'wanda': 'sharp trailer park manager with glasses on a chain', 'gary': 'overzealous mall security guard'}
AREA_DESC = {'town': 'Old West frontier town at sunset with wooden false-front buildings, a saloon, and a faintly glowing portal arch where worlds meet', 'forest': 'misty enchanted fantasy forest at dusk with shafts of light', 'crypt': 'ancient fantasy crypt with stone arches, bones and torchlight', 'marsh': 'foggy fantasy swamp with dead trees, reeds and fireflies',
             'road': 'Old West desert trail at sunset with red rocks, a wooden sign and telegraph wires', 'mines': 'Old West gold-rush mine tunnel with rail tracks, lantern light and glowing crystals', 'dunes': 'fantasy desert dunes at sunset with ancient ruins', 'frost': 'sci-fi research station on a frozen moon with aurora and snow mountains', 'ember': 'sci-fi volcanic colony world with lava rivers and ash',
             'citadel': 'ruined fantasy castle towers under moonlight and mist', 'abyss': 'cosmic sci-fi void with a swirling dark vortex and violet light', 'gulch': 'Old West ghost town at night with pale wisps and a glowing portal arch', 'thorn': 'fey forest with giant glowing mushrooms and fireflies', 'aurora': 'wrecked starship corridor lit by red emergency lights', 'reach': 'sunken fantasy kingdom underwater with light rays and coral', 'modern': 'big-box superstore storefront with a red sign and a parking lot', 'bank': 'grand Old West bank building front at golden hour', 'rail': 'hellish railroad yard with tracks into a glowing tunnel and a locomotive headlight'}
